function deityLawDirection(deity) {
  if (!deity) return 0;
  const sign = (
    /** @type {Record<string, number>} */
    DEITY_LAW_TUNING.axisSign[deity.lawAxis]
  );
  return (
    /** @type {-1|0|1} */
    Number.isFinite(sign) ? sign : 0
  );
}
