// src/domain/facts/dangerComing.js
function dangerComingOf(record) {
  const tensions = (
    /** @type {{ history?: { currentTensions?: unknown } | null } | null} */
    record?.history?.currentTensions
  );
  return Array.isArray(tensions) && tensions.some((t) => !!t && typeof t === "object" && /** @type {{ type?: unknown }} */
  t.type === "external_threat");
}

// src/data/monsterThreat.js
var MONSTER_THREAT_TIERS = Object.freeze(["heartland", "frontier", "plagued"]);
var MONSTER_THREAT_RANDOM_POOL = Object.freeze([
  "heartland",
  "heartland",
  "frontier",
  "frontier",
  "frontier",
  "plagued"
]);
function normalizeMonsterThreat(raw) {
  const mt = raw || "frontier";
  return mt === "low" ? "heartland" : mt === "high" ? "plagued" : mt === "medium" ? "frontier" : mt;
}

// src/domain/facts/scoreBandCuts.js
var SCORE_BAND_CUTS = Object.freeze({ strong: 65, adequate: 40, weak: 20 });

// src/domain/facts/monsterFrontier.js
function monsterFrontierOf(record) {
  const r = record && typeof record === "object" ? (
    /** @type {{ config?: { monsterThreat?: unknown }, defenseProfile?: { scores?: { monster?: unknown } } }} */
    record
  ) : {};
  const raw = r.config?.monsterThreat;
  if (typeof raw !== "string" || !raw) return false;
  const family = normalizeMonsterThreat(raw);
  if (family === "plagued") return true;
  if (family !== "frontier") return false;
  const score = r.defenseProfile?.scores?.monster;
  return (typeof score === "number" && Number.isFinite(score) ? score : 0) < SCORE_BAND_CUTS.adequate;
}

// src/domain/facts/growsMoreThanEats.js
function growsMoreThanEatsOf(record) {
  const fr = (
    /** @type {{ economicState?: { foodSecurity?: { foodRecord?: { growsMoreThanEats?: unknown } | null } | null } | null } | null} */
    record?.economicState?.foodSecurity?.foodRecord
  );
  return !!fr && fr.growsMoreThanEats === true;
}

// src/domain/facts/legacyRuin.js
var RUINOUS_EVENT_TYPES = Object.freeze(["disaster"]);
var RUINOUS_TEMPLATE_TYPES = Object.freeze(["great_fire", "great_flood", "plague_years", "external_threat", "occupation_legacy"]);
var nameKey = (name) => String(name ?? "").trim().toLowerCase().replace(/^the\s+/, "");
function legacyRuinOf(record) {
  const history = (
    /** @type {{ history?: { legacyAnnotations?: unknown, historicalEvents?: unknown } | null } | null | undefined} */
    record?.history
  );
  if (!history || typeof history !== "object") return void 0;
  const top = Array.isArray(history.legacyAnnotations) ? history.legacyAnnotations[0] : null;
  const named = nameKey(
    /** @type {{ eventName?: unknown } | null} */
    top?.eventName
  );
  if (!named) return false;
  const events = Array.isArray(history.historicalEvents) ? history.historicalEvents : [];
  return events.some((e) => nameKey(e?.name) === named && (RUINOUS_EVENT_TYPES.includes(String(e?.type ?? "")) || RUINOUS_TEMPLATE_TYPES.includes(String(e?.templateType ?? ""))));
}

