// src/domain/facts/warIronHook.js
var IRON_GOODS = /\b(?:iron|metal)/i;
var ironHookStands = (resource, held) => /metal|iron/.test(String(resource ?? "").toLowerCase()) && held(IRON_GOODS);
var OCCUPATION_TYPES = Object.freeze(["occupied", "occupation"]);
function ironWarState(warState, stressTypes) {
  if (warState !== "at war" || !Array.isArray(stressTypes)) return warState;
  const types = stressTypes.map((t) => String(t ?? ""));
  return types.some((t) => OCCUPATION_TYPES.includes(t)) && !types.includes("wartime") ? "peace" : warState;
}
var warIronState = (warState, stressTypes) => ironWarState(warState, stressTypes) !== "peace";
function warHoldsIron(dependencies, imports, warState, stressTypes) {
  if (!warIronState(warState, stressTypes)) return false;
  const held = (pattern) => imports.some((x) => typeof x === "string" && pattern.test(x));
  return dependencies.some((d) => {
    const m = /^Imports (.+)$/.exec(String(
      /** @type {{ title?: unknown } | null} */
      d?.title ?? ""
    ));
    return !!m && ironHookStands(m[1], held);
  });
}

